### C++

```C++
#include <bits/stdc++.h>
using namespace std;
const int maxn = 2e5 + 5;
int e[maxn][2] , d[maxn] , dp[maxn];
void dfs (int u){
    // l , r为左右儿子节点
    int l = e[u][0];
    int r = e[u][1];
    // 转移case 1,也是边界条件
    if (l == -1 && r == -1) {
        dp[u] = 1;
        return;
    }
    if (l != -1) dfs(l);
    if (r != -1) dfs(r);
    // 转移case 2
    if (l != -1 && r != -1 && dp[l] == dp[r] && dp[l] != 0) dp[u] = dp[l] + 1;
    // 转移case 3
    else dp[u] = 0;
}
int main() {
    int n;
    cin >> n;
    // 读入图
    for (int i = 1 ; i <= n ; i++){
        cin >> e[i][0] >> e[i][1];
        // d用来记录度数
        if (e[i][0] != -1) d[e[i][0]]++;
        if (e[i][1] != -1) d[e[i][1]]++;
    }
    // 寻找根
    int rt = -1;
    for (int i = 1 ; i <= n ; i++)
        if (d[i] == 0)
            rt = i;
   	// 从根开始dfs
    dfs(rt);
    // 求答案
    int ans = 0;
    for (int i = 1 ; i <= n ; i++)
        ans += (dp[i] != 0);
    cout << ans << endl;
	return 0;
}

