#include<bits/stdc++.h>
using namespace std;

void dfs(vector<int>& dp, int node, vector<vector<int>>& child) {
    int left = child[node][0];
    int right = child[node][1];
    if (left == -1 && right == -1) {
        dp[node] = 1;
        return;
    } 
    if (left != -1) dfs(dp, left, child);
    if (right != -1) dfs(dp, right, child);
    if ((right != -1 && left != -1) && (dp[right] == dp[left]) && dp[right] != 0) {
        dp[node] = dp[left] + 1;
    } else {
        dp[node] = 0;
    }

}

int main() {
    int n;
    cin >> n;
    vector<int> in_du(n+1, 0);
    vector<int> dp(n+1, 0);
    vector<vector<int>> child(n+1, vector<int>(2));
    for (int i = 1; i <= n; i++) {
        int left, right;
        cin >> left >> right;
        if (left != -1)
            in_du[left]++;
        if (right != -1)
            in_du[right]++;
        child[i][0] = left;
        child[i][1] = right;
    }
    int root;
    for (int i = 1; i <= n; i++) {
        if (in_du[i] == 0) {
            root = i;
            break;
        }
    }
    dfs(dp, root, child);
    int ans =  0;
    for(int i = 1; i <= n; i++) {
        if (dp[i] != 0) ans++;
        // cout << i <<' ' << dp[i] << endl;
    }
    cout << ans;
}
