import java.util.Scanner;

class TreeNode{
    int val;
    TreeNode left;
    TreeNode right;
}

public class Main {

    public static void main(String[] args) {
        Scanner in = new Scanner(System.in);
        int n = in.nextInt();
        TreeNode[] nodes = new TreeNode[n];
        for(int i=0;i<n;i++) nodes[i] = new TreeNode();
        for(int i=0;i<n;i++){
            int l = in.nextInt();
            int r = in.nextInt();
            if(l!=-1) nodes[i].left = nodes[l-1];
            if(r!=-1) nodes[i].right = nodes[r-1];
        }
        int result = 0;
        for(int i=0;i<n;i++){
            if(isFull(nodes[i])) result++;
        }
        System.out.println(result);
    }

    public static boolean isFull(TreeNode tree){
        if(tree==null) return true;
        TreeNode p = tree;
        int l =0;
        while (p!=null){
            l++;
            p = p.left;
        }
        int r = 0;
        p = tree;
        while (p!=null){
            r++;
            p = p.right;
        }
        return l==r && isFull(tree.left) && isFull(tree.right);
    }
}
